shard.installScript:
#!/bin/bash
# Midnight Reverse Proxy Installation Script
set -e
apk add --no-cache curl tar

cd /mnt/server
ARCH=$(uname -m)
if [ "$ARCH" = "x86_64" ]; then
    BIN_ARCH="linux_amd64"
elif [ "$ARCH" = "aarch64" ]; then
    BIN_ARCH="linux_arm64"
else
    BIN_ARCH="linux_amd64"
fi

echo "Downloading Caddy core for $BIN_ARCH..."
curl -sSL -o caddy.tar.gz "https://github.com/caddyserver/caddy/releases/latest/download/caddy_${BIN_ARCH#linux_}_${BIN_ARCH}.tar.gz"
tar -xzf caddy.tar.gz caddy
rm -f caddy.tar.gz
chmod +x caddy

if [ ! -f "Caddyfile" ]; then
cat << 'EOF' > Caddyfile
:{{SERVER_PORT}} {
    reverse_proxy {{UPSTREAM_TARGET}} {
        header_up Host {upstream_hostport}
        header_up X-Real-IP {remote_host}
        header_up X-Forwarded-For {remote_host}
        header_up X-Forwarded-Proto {scheme}
    }
    log {
        output file /home/container/access.log
    }
}
EOF
fi

echo "Midnight Reverse Proxy installation complete!"
